/* Standalone product prototype. All seed people and events are fictional. */
'use strict';
const $ = (selector) => document.querySelector(selector);
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths = {home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',photo:'M3 3h18v18H3zM3 16l6-6 5 5 3-3 4 4M16 7h.01',chart:'M4 21V11M12 21V3M20 21v-7',plus:'M12 5v14M5 12h14',back:'m15 18-6-6 6-6',calendar:'M4 5h16v16H4zM16 3v4M8 3v4M4 11h16',settings:'M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',restore:'M3 10a9 9 0 1 1 2 9M3 4v6h6M12 7v5l3 2',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',edit:'m15 4 5 5M3 21l5-1L21 7l-5-5L3 15z',file:'M14 2H5v20h14V7zM14 2v6h5M8 13h8M8 17h5',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name] || iconPaths.photo}"/></svg>`;
const initial = {
 // These are fictional user's own types, not fixed product categories.
 types:[{id:'t1',name:'3寸'},{id:'t2',name:'5寸'},{id:'t3',name:'合照'},{id:'t4',name:'单人'},{id:'t5',name:'宿题'},{id:'t6',name:'主题'}],
 targets:[{id:'a',kind:'idol',name:'小凪',group:'月面来信',tone:''},{id:'b',kind:'idol',name:'柚子',group:'晴空放送',tone:'blue'},{id:'c',kind:'idol',name:'梨奈',group:'月面来信',tone:'gold'},{id:'g1',kind:'group',name:'月面来信',group:'团体',tone:'blue'},{id:'g2',kind:'group',name:'晴空放送',group:'团体',tone:'gold'}],
 events:[{id:'e1',date:'2026-10-11',name:'秋日来信 · 联合公演',place:'上海 · 星屿 Livehouse'},{id:'e2',date:'2026-10-05',name:'月面来信 · 午后专场',place:'上海 · 星屿 Livehouse'},{id:'e3',date:'2026-10-01',name:'假日的第一场见面',place:'上海 · 白昼空间'}],
 records:[{id:'r1',date:'2026-10-11',event:'e1',kind:'regular',targetId:'a',participantIds:[],typeId:'t1',qty:2,amount:100,priceMode:'unit',unit:50},{id:'r2',date:'2026-10-11',event:'e1',kind:'regular',targetId:'a',participantIds:[],typeId:'t2',qty:1,amount:80,priceMode:'unit',unit:80},{id:'r3',date:'2026-10-11',event:'e1',kind:'regular',targetId:'b',participantIds:[],typeId:'t4',qty:3,amount:150,priceMode:'unit',unit:50},{id:'r4',date:'2026-10-11',event:null,kind:'regular',targetId:'g1',participantIds:[],typeId:'t6',qty:1,amount:null,priceMode:'total',unit:null},{id:'r5',date:'2026-10-05',event:'e2',kind:'regular',targetId:'a',participantIds:[],typeId:'t5',qty:3,amount:240,priceMode:'unit',unit:80},{id:'r6',date:'2026-10-05',event:'e2',kind:'regular',targetId:'c',participantIds:[],typeId:'t3',qty:2,amount:100,priceMode:'unit',unit:50},{id:'r7',date:'2026-10-01',event:'e3',kind:'regular',targetId:'b',participantIds:[],typeId:'t4',qty:3,amount:150,priceMode:'unit',unit:50},{id:'r8',date:'2026-10-01',event:'e3',kind:'regular',targetId:'a',participantIds:[],typeId:'t5',qty:2,amount:160,priceMode:'unit',unit:80},{id:'r9',date:'2026-10-11',event:null,kind:'special',targetId:null,participantIds:['a','b'],typeId:'t3',qty:1,amount:120,priceMode:'total',unit:null}],
 photos:[{id:'p1',record:'r2'},{id:'p2',record:'r3'},{id:'p3',record:'r5'},{id:'p4',record:'r6'}]
};
let db = structuredClone(initial);
let activeDate = '2026-10-11', activeTarget = 'a', albumTarget = 'all', profileMode = 'idol', statPeriod = 'month';
let draft = {}, batchRows = [], batchInfo = {};
let undo = null, toastTimer;
const scenes = [
 ['home','日期首页','先看日期，再看记录','按天回顾和谁拍了多少张，不需要先创建或填写活动。',['首页底部悬浮速记与补录入口，滚动列表时仍可操作。','最近常拍头像直达录入，默认今天。','每天的记录混合展示，无活动与有活动都正常统计。']],
 ['quick','快速记录','选好日期，就能记一笔','日期是主线。活动和照片都可以不填，不增加保存门槛。',['日期默认今天，可直接补录过去某一天。','个人、团体、特殊 cheki 都共享自定义单选类型。','活动放在可展开的选填区域，留空不提示补全。']],
 ['batch','按日补录','把这一天慢慢补齐','同一天的多人、多类型拍立得，可以一次录完。',['先选日期，活动名称可完全留空。','每条明细独立调整张数和金额。','保存会追加记录到该日期，不创建“未命名活动”。']],
 ['day','当日记录','这一天，都在这里','日期是页面标题，活动仅在填过时作为辅助信息出现。',['当天全部记录按日期聚合，跨活动与无活动一起统计。','金额待补有提醒，未填活动没有提醒。','编辑日期后，记录移到正确的一天。']],
 ['idol','偶像','每次见面，都算数','个人、团体独立计数，特殊 cheki 单独收藏。',['统计有记录的天数，不把一天多笔当成多次见面。','时间线以日期为标题，无需活动名。','特殊 cheki 可关联多人，不增加任何人的常规切数。']],
 ['stats','统计','按日期看清数量和花费','每天、每月、每年都从记录日期计算。',['按月、年或全部切换范围。','图表展示每天的常规切数，自定义类型按单选统计。','未填活动不影响任何统计口径。']],
 ['album','相册','让日期，也有画面','照片按记录日期回顾，无需先有活动。',['个人、团体、特殊 cheki 可分别筛选，按日期排列。','点开照片可回到对应日期及记录。','照片增删不改变张数或金额。']],
 ['data','数据管理','记录要带得走','完整备份保留日期、对象、特殊参与者、类型、照片与关联。',['备份不依赖活动是否填写。','CSV 区分常规与特殊，保留参与者和计数标记。','ZIP 与恢复在原型中演示流程，CSV 可实际下载。']]
];
let currentScreen = new URLSearchParams(location.search).get('screen') || 'home';
if (!scenes.some(s=>s[0]===currentScreen)) currentScreen='home';
if(new URLSearchParams(location.search).has('capture')) document.body.classList.add('capture');
const target = id => db.targets.find(i=>i.id===id);
const targetsOf = kind => db.targets.filter(t=>t.kind===kind);
const modeNames = {idol:'个人',group:'团体',special:'特殊 cheki'};
const recordTarget = r => r.kind==='special' ? {name:r.participantIds.map(id=>target(id)?.name||'已归档偶像').join(' × '),group:'特殊 cheki',tone:'violet'} : target(r.targetId);
const recordLabel = r => r.kind==='special'?'特殊 cheki':target(r.targetId)?.kind==='group'?'团切':'个人切';
const matchesTarget = (r,id) => r.kind==='regular'&&r.targetId===id;
const draftMode = () => draft.kind==='special'?'special':target(draft.targetId)?.kind||'idol';
const validTarget = r => r.kind==='special' ? r.targetId===null&&r.participantIds.length>0&&new Set(r.participantIds).size===r.participantIds.length&&r.participantIds.every(id=>target(id)?.kind==='idol') : r.kind==='regular'&&!!target(r.targetId)&&r.participantIds.length===0;
const countLabel = s => `${s.qty} 张常规${s.specialQty?` · ${s.specialQty} 张特殊`:''}`;
const modeSwitch = (mode,attribute) => `<div class="period-switch target-switch">${Object.entries(modeNames).map(([k,v])=>`<button class="${mode===k?'active':''}" ${attribute}="${k}" aria-pressed="${mode===k}">${v}</button>`).join('')}</div>`;
function targetOptions(r){return `<optgroup label="个人">${targetsOf('idol').map(t=>`<option value="${t.id}" ${r.targetId===t.id?'selected':''}>${escapeHtml(t.name)}</option>`).join('')}</optgroup><optgroup label="团体">${targetsOf('group').map(t=>`<option value="${t.id}" ${r.targetId===t.id?'selected':''}>${escapeHtml(t.name)}</option>`).join('')}</optgroup>`;}
function specialSummary(s){return s.specialQty?`<div class="special-summary"><span>特殊 cheki <strong>${s.specialQty} 张</strong> · ${money(s.specialAmount)}</span><small>数量另记，不计入常规切数；花费已含在总花费中</small></div>`:'';}
function applyDraftMode(mode){if(mode==='special'){draft.participantIds=target(draft.targetId)?.kind==='idol'?[draft.targetId]:[];draft.kind='special';draft.targetId=null;}else{draft.kind='regular';draft.targetId=targetsOf(mode)[0]?.id||null;draft.participantIds=[];}render();}

const event = id => db.events.find(e=>e.id===id) || null;
const dates = rows => [...new Set(rows.map(r=>r.date))].sort((a,b)=>b.localeCompare(a));
const dayLabel = date => `${Number(date.slice(5,7))}月${Number(date.slice(8))}日`;
const weekday = date => ['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][new Date(date+'T12:00:00').getDay()];
const validDate = date => /^\d{4}-\d{2}-\d{2}$/.test(date) && !Number.isNaN(Date.parse(date+'T12:00:00')) && new Date(date+'T12:00:00Z').toISOString().slice(0,10)===date;
function resolveEvent(name){name=name.trim();if(!name)return null;const existing=db.events.find(e=>e.name===name);if(existing)return existing.id;const id='e'+Date.now();db.events.push({id,name});return id;}
function optionalEventInput(prefix,name){return `<details class="optional-event" ${name?'open':''}><summary><span>活动 <small>选填</small></span><span>${name?escapeHtml(name):'不填写也能保存'} ＋</span></summary><input class="input" id="${prefix}-event" list="${prefix}-events" value="${escapeHtml(name)}" placeholder="可输入或选择活动，留空即可" aria-label="活动名称（选填）"><datalist id="${prefix}-events">${db.events.map(e=>`<option value="${escapeHtml(e.name)}">`).join('')}</datalist></details>`;}
const typeName = record => db.types.find(t=>t.id===record.typeId)?.name || '';
const typeText = record => typeName(record) || '未填写';
const typeQuantity = (rows,id) => sum(rows.filter(r=>r.typeId===id)).qty;
const sum = records => ({qty:records.filter(r=>r.kind==='regular').reduce((n,r)=>n+r.qty,0),specialQty:records.filter(r=>r.kind==='special').reduce((n,r)=>n+r.qty,0),amount:records.reduce((n,r)=>n+(r.amount??0),0),specialAmount:records.filter(r=>r.kind==='special').reduce((n,r)=>n+(r.amount??0),0),pending:records.filter(r=>r.amount===null).length});
const money = n => n===null ? '待补金额' : '¥'+Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2});
const photoCount = records => db.photos.filter(p=>records.some(r=>r.id===p.record)).length;
const avatar = (i,cls='') => `<span class="avatar ${i.tone} ${cls}">${escapeHtml(i.name.slice(-1))}</span>`;
const header = (title,subtitle='',back=false,action='settings')=>`<header class="header"><div class="left">${back?`<button class="icon-button plain" data-go="home" aria-label="返回首页">${icon('back')}</button>`:''}<div><h2>${title}</h2>${subtitle?`<div class="subheading">${subtitle}</div>`:''}</div></div><button class="icon-button" data-go="${action==='settings'?'data':'quick'}" aria-label="${action==='settings'?'数据管理':'记一笔'}">${icon(action)}</button></header>`;
const bottom = active => `<nav class="bottom-nav" aria-label="主导航">${[['home','home','日记'],['idol','people','偶像'],['album','photo','相册'],['stats','chart','统计']].map(([s,i,t])=>`<button data-go="${s}" class="${active===s?'active':''}">${icon(i)}${t}</button>`).join('')}</nav>`;
const metrics = (s,small=false)=>`<div class="metrics"><div class="metric"><strong>${s.qty}</strong><span class="unit">张</span><div class="label">${small?'当天常规切数':'常规切数'}</div></div><div class="metric"><strong>${s.amount.toLocaleString('zh-CN')}</strong><span class="unit">元</span><div class="label">已记录总花费</div></div></div>`;
const photo = (p,mini=false)=>{const r=db.records.find(r=>r.id===p.record);if(!r)return '';const i=recordTarget(r);return `<button class="polaroid" data-photo="${p.id}" aria-label="查看${escapeHtml(i.name)}的照片"><div class="photo-art ${i.tone}">${p.src?`<img src="${p.src}" alt="${escapeHtml(i.name)}的拍立得">`:'<span class="arc"></span><span class="star">✦</span><span class="sample-label">SAMPLE</span>'}</div><span class="caption">${escapeHtml(i.name)} · ${escapeHtml(typeText(r))}</span><span class="caption-meta">${r.date.replaceAll('-','.')}　${mini?'':escapeHtml(i.group)}</span></button>`};
function dateCard(date){const rows=db.records.filter(r=>r.date===date),s=sum(rows),ids=[...new Set(rows.filter(r=>r.kind==='regular').map(r=>r.targetId))];return `<button class="event-card date-card" data-date="${date}"><div class="row"><h4>${dayLabel(date)} <span class="weekday">${weekday(date)}</span></h4>${date==='2026-10-11'?'<span class="pill rose">今天</span>':''}</div><div class="location">${date.slice(0,4)} 年 · ${rows.length} 笔记录 · ${photoCount(rows)} 张照片</div><div class="event-total row"><div class="avatar-stack">${ids.slice(0,4).map(id=>avatar(target(id),'sm')).join('')}</div><span><strong>${s.qty}</strong> 张常规 · ${money(s.amount)}</span></div>${s.specialQty?`<div class="inline-note">另有 ${s.specialQty} 张特殊 cheki · 不计入常规切数</div>`:''}${s.pending?'<div class="inline-note">有金额待补</div>':''}</button>`}
function renderHome(){const rows=db.records.filter(r=>r.date.startsWith('2026-10')),s=sum(rows);return header('推活日记','SUNDAY, OCTOBER 11')+`<div class="body"><div class="hero"><div class="hero-top"><span>2026 年 10 月</span><span class="pill">记录 ${dates(rows).length} 天</span></div>${metrics(s)}${specialSummary(s)}<div class="hero-bottom">${s.pending?`<button data-date="${rows.find(r=>r.amount===null).date}">${s.pending} 笔金额待补，数量已分别记录　↗</button>`:'这个月的每一次见面，都记住了。'}</div></div><div class="section-heading"><h3>最近常拍</h3><button data-go="idol">全部偶像 ↗</button></div><div class="idol-row">${[...targetsOf('idol').slice(0,2),...targetsOf('group').slice(0,1)].map(i=>`<button class="idol-shortcut" data-quick-target="${i.id}">${avatar(i)}${escapeHtml(i.name)}</button>`).join('')}<button class="idol-shortcut" data-action="add-idol"><span class="avatar add">+</span>新增偶像</button></div><div class="section-heading"><h3>按日期回顾</h3><span class="small muted">${dates(db.records).length} 个记录日</span></div>${dates(db.records).map(dateCard).join('')||'<div class="empty-note">先记下第一张拍立得吧。</div>'}</div><div class="home-floating-actions" role="group" aria-label="记录拍立得"><button class="primary" data-go="quick">${icon('plus')}快速记一笔</button><button class="secondary" data-go="batch">${icon('calendar')}按日补录</button></div>`+bottom('home')}
function initDraft(id){const r=id?db.records.find(r=>r.id===id):null;draft=r?{...r,participantIds:[...r.participantIds],eventName:event(r.event)?.name||'',photos:[]}:{date:currentScreen==='day'?activeDate:'2026-10-11',event:null,eventName:'',kind:'regular',targetId:activeTarget,participantIds:[],typeId:null,qty:1,amount:50,priceMode:'unit',unit:50,photos:[]}}
function renderQuick(){if(!Object.keys(draft).length)initDraft();return header(draft.id?'编辑记录':'快速记一笔','',true)+`<div class="body"><div class="date-context">${icon('calendar')}<div><label for="quick-date">记录日期</label><input type="date" id="quick-date" value="${draft.date}" required></div><span class="pill">${draft.date==='2026-10-11'?'今天':weekday(draft.date)||'选择日期'}</span></div><label class="field-label">记录对象</label>${modeSwitch(draftMode(),'data-draft-mode')}<div class="choices person-choices">${targetsOf(draftMode()==='special'?'idol':draftMode()).map(i=>`<button class="person-option ${(draft.kind==='special'?draft.participantIds.includes(i.id):draft.targetId===i.id)?'selected':''}" data-select-target="${i.id}" aria-pressed="${draft.kind==='special'?draft.participantIds.includes(i.id):draft.targetId===i.id}">${avatar(i)}${escapeHtml(i.name)}</button>`).join('')}</div>${draft.kind==='special'?'<p class="inline-note special-note">偶像可多选 · 不计入总切数及个人切数</p>':'<p class="inline-note">只选一个对象 · 团切不分摊给成员</p>'}<div class="row"><label class="field-label">自定义类型<span class="optional">选填 · 单选</span></label><button class="tag-manage" data-action="manage-types">管理</button></div><div class="choices tag-choices">${db.types.map(t=>`<button class="chip ${draft.typeId===t.id?'selected':''}" data-type-id="${t.id}" aria-pressed="${draft.typeId===t.id}">${escapeHtml(t.name)}</button>`).join('')||'<button class="chip" data-action="manage-types">+ 创建自己的类型</button>'}</div><label class="field-label" for="quick-qty">拍了几张</label><div class="counter"><button data-qty="-1" aria-label="减少一张">−</button><div><input id="quick-qty" type="number" min="1" max="999" value="${draft.qty}" aria-label="拍立得张数"><span>张</span></div><button data-qty="1" aria-label="增加一张">+</button></div><div class="row"><label class="field-label" for="quick-amount">${draft.priceMode==='unit'?'每张单价':'本笔实付'}<span class="optional">可稍后补</span></label><span class="small muted">人民币</span></div><div class="amount-field"><span>¥</span><input id="quick-amount" type="number" min="0" step="0.01" inputmode="decimal" placeholder="暂不填写" value="${draft.priceMode==='unit'?(draft.unit??''):(draft.amount??'')}"></div><div class="money-toggle"><label><input type="radio" name="money-mode" value="unit" ${draft.priceMode==='unit'?'checked':''}>按单价计算</label><label><input type="radio" name="money-mode" value="total" ${draft.priceMode==='total'?'checked':''}>直接填总额</label></div>${optionalEventInput('quick',draft.eventName)}<label class="field-label">留下照片<span class="optional">选填</span></label><button class="upload" data-action="upload">${icon('photo')}<span><strong>${draft.photos.length?`已选择 ${draft.photos.length} 张照片`:'添加照片'}</strong><small>可以回家再补，不影响张数统计</small></span></button><input id="photo-upload" type="file" accept="image/*" multiple hidden><p class="inline-note">${draft.id?'修改已有记录，不会重复新增。':'一笔可以记多张，活动不填也能保存。'}</p></div><div class="form-footer"><div class="summary row"><span>本笔合计</span><strong id="quick-summary">${draft.qty} 张 · ${money(draft.amount)}</strong></div><button class="primary" data-action="save-quick">${draft.id?'保存修改':'保存记录'}</button></div>`}
function initBatch(){batchInfo={name:'',date:'2026-10-11'};batchRows=initial.records.slice(0,3).map(r=>({...r,event:null,id:'b'+r.id}))}
function renderBatch(){if(!batchRows.length&&!batchInfo.date)initBatch();const s=sum(batchRows);return header('按日补录','',true)+`<div class="body"><p class="page-intro">选择一天，把和谁拍了多少张，一次记齐。</p><div class="date-context">${icon('calendar')}<div><label for="batch-date">记录日期</label><input type="date" id="batch-date" value="${batchInfo.date}" required></div><span class="pill">可补过去的记录</span></div>${optionalEventInput('batch',batchInfo.name)}<div class="section-heading"><h3>拍摄明细</h3><span class="small muted">${batchRows.length} 笔</span></div>${batchRows.map((r,n)=>`<div class="batch-card"><div class="row"><div class="row">${avatar(recordTarget(r),'sm')}<div><div class="name">${escapeHtml(recordTarget(r).name)}</div><div class="type">${escapeHtml(typeText(r))} · ${r.priceMode==='unit'?money(r.unit)+'/张':'实付总额'}</div></div></div><button class="amount" data-batch-edit="${n}" aria-label="编辑第${n+1}笔">${money(r.amount)}</button></div><div class="row"><div class="mini-counter"><button data-batch-delta="${n},-1" aria-label="第${n+1}笔减少一张">−</button><span>${r.qty} 张</span><button data-batch-delta="${n},1" aria-label="第${n+1}笔增加一张">+</button></div><button class="remove" data-batch-remove="${n}">移除</button></div></div>`).join('')}<button class="dashed-button" data-action="batch-add">+ 添加一笔明细</button><p class="inline-note">活动和照片都可以不填。保存后仍能逐笔补充。</p></div><div class="form-footer"><div class="summary row"><span>本次新增${s.pending?` · ${s.pending} 笔金额待补`:''}</span><strong>${countLabel(s)} · ${money(s.amount)}</strong></div><button class="primary" data-action="save-batch">保存到 ${dayLabel(batchInfo.date)}</button></div>`}
function renderDay(){const rows=db.records.filter(r=>r.date===activeDate),s=sum(rows);return header('当日记录','',true,'plus')+`<div class="body"><div class="event-hero day-hero"><div class="date">${activeDate.slice(0,4)} 年　/　DAILY DIARY</div><h3>${dayLabel(activeDate)} <span>${weekday(activeDate)}</span></h3><div class="place">${rows.length} 笔记录 · 个人 / 团体 / 特殊</div>${metrics(s,true)}${specialSummary(s)}</div>${s.pending?`<div class="warning-strip"><span>${s.pending} 笔金额待补，当前显示已记录花费</span><button data-edit="${rows.find(r=>r.amount===null).id}">去补全</button></div>`:''}<div class="section-heading"><h3>这一天的拍立得</h3><span class="small muted">${photoCount(rows)} 张照片</span></div>${rows.map(r=>`<div class="detail-row"><div class="row"><div class="row">${avatar(recordTarget(r),'sm')}<div><div class="name">${escapeHtml(recordTarget(r).name)} ${typeName(r)?`<span class="pill">${escapeHtml(typeName(r))}</span>`:''}</div><div class="meta">${recordLabel(r)}${event(r.event)?' · '+escapeHtml(event(r.event).name):''}${photoCount([r])?' · 已附照片':''}</div></div></div><div class="value">${r.qty} 张<br><span class="small muted">${money(r.amount)}</span></div></div><div class="subactions"><button data-edit="${r.id}">编辑</button><button data-remove="${r.id}">删除</button><button data-add-one="${r.id}">再拍 +1</button></div></div>`).join('')}${!rows.length?'<div class="empty-note">这一天还没有记录，先记下第一张吧。</div>':''}</div><div class="form-footer"><button class="primary" data-go="quick">${icon('plus')}继续记这一天</button></div>`}
function renderIdol(){if(profileMode==='special')return renderSpecial();const list=targetsOf(profileMode);if(!list.some(t=>t.id===activeTarget))activeTarget=list[0]?.id;const i=target(activeTarget);if(!i)return header('我的偶像')+`<div class="body">${modeSwitch(profileMode,'data-profile-mode')}<button class="primary" data-action="add-group">新增团体</button></div>`+bottom('idol');const rows=db.records.filter(r=>matchesTarget(r,i.id)),s=sum(rows),ids=dates(rows);return header('我的偶像','',false,'plus')+`<div class="body">${modeSwitch(profileMode,'data-profile-mode')}<div class="choices person-choices">${list.map(t=>`<button class="chip ${t.id===activeTarget?'selected':''}" data-target="${t.id}">${escapeHtml(t.name)}</button>`).join('')}<button class="chip" data-action="${profileMode==='group'?'add-group':'add-idol'}">+ 新增</button></div><div class="idol-profile" style="margin-top:18px">${avatar(i)}<h3>${escapeHtml(i.name)}</h3><p>${i.kind==='group'?'团体 cheki 独立统计，不分摊给成员':escapeHtml(i.group||'个人偶像')+' · 不含参与的特殊 cheki'}</p></div><div class="profile-stats"><div><strong>${s.qty}</strong><span>${i.kind==='group'?'累计团切':'累计个人切'} / 张</span></div><div><strong>${money(s.amount)}</strong><span>已记录花费</span></div><div><strong>${ids.length}</strong><span>有记录的天数</span></div></div>${s.pending?`<div class="warning-strip">还有 ${s.pending} 笔金额待补</div>`:''}<button class="primary" style="width:100%" data-quick-target="${i.id}">${icon('plus')}再记一笔</button><div class="section-heading"><h3>见面时间线</h3><span class="small muted">${ids.length} 天</span></div><div class="timeline">${ids.map(date=>{const rs=rows.filter(r=>r.date===date),s=sum(rs);return `<button class="timeline-item" data-date="${date}" style="display:block;text-align:left;width:100%"><div class="date">${date.slice(0,4)} 年 · ${weekday(date)}</div><h4>${dayLabel(date)}</h4><p>${s.qty} 张 · ${money(s.amount)}</p></button>`}).join('')||'<div class="empty-note">还没有记录。</div>'}</div><div class="section-heading"><h3>收藏的瞬间</h3><button data-album-target="${i.id}">全部照片 ↗</button></div><div class="photo-grid album-mini">${db.photos.filter(p=>rows.some(r=>r.id===p.record)).slice(0,2).map(p=>photo(p,true)).join('')||'<div class="empty-note">照片可以之后再补。</div>'}</div>${i.kind==='idol'?`<button class="dashed-button" data-special-person="${i.id}">查看 TA 参与的特殊 cheki（不计入个人切数）</button>`:''}</div>`+bottom('idol')}
let specialPerson = 'all';
function renderSpecial(){const rows=db.records.filter(r=>r.kind==='special'&&(specialPerson==='all'||r.participantIds.includes(specialPerson))),s=sum(rows);return header('我的偶像')+`<div class="body">${modeSwitch('special','data-profile-mode')}<div class="special-hero"><span class="eyeline">SPECIAL COLLECTION</span><h3>特别的同框，单独收藏。</h3><div class="row"><strong>${s.specialQty} 张特殊 cheki</strong><span>${money(s.amount)}</span></div><p>数量不计入常规切数与个人切数。<br>花费只计一次，已包含在总花费中。</p></div><div class="choices"><button class="chip ${specialPerson==='all'?'selected':''}" data-special-person="all">全部</button>${targetsOf('idol').map(i=>`<button class="chip ${specialPerson===i.id?'selected':''}" data-special-person="${i.id}">${escapeHtml(i.name)}</button>`).join('')}</div><p class="inline-note">按参与偶像查找，同一笔只展示一次</p><button class="primary special-add" data-action="new-special">+ 记录特殊 cheki</button>${rows.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<button class="special-card" data-edit="${r.id}"><span class="row"><strong>${escapeHtml(recordTarget(r).name)}</strong><span>${r.qty} 张</span></span><span class="small muted">${r.date} · ${escapeHtml(typeText(r))} · ${money(r.amount)}</span></button>`).join('')||'<div class="empty-note">还没有特殊 cheki，可以随时添加。</div>'}</div>`+bottom('idol')}
function renderStats(){let rows=db.records.filter(r=>statPeriod==='all'||r.date.startsWith(statPeriod==='year'?'2026':'2026-10'));const s=sum(rows);const es=dates(rows).reverse();const max=Math.max(1,...es.map(date=>sum(rows.filter(r=>r.date===date)).qty));return header('见面的统计','每一张，都有迹可循')+`<div class="body"><div class="period-switch">${[['month','本月'],['year','本年'],['all','全部']].map(([k,v])=>`<button class="${statPeriod===k?'active':''}" data-period="${k}">${v}</button>`).join('')}</div><div class="hero" style="margin-top:13px"><div class="hero-top"><span>${statPeriod==='month'?'2026 年 10 月':statPeriod==='year'?'2026 年':'全部记录'}</span><span class="pill">${es.length} 个记录日</span></div>${metrics(s)}${specialSummary(s)}<div class="hero-bottom">${s.pending?`${s.pending} 笔金额待补 · 数量已分别记录`:'所有金额已补齐'}</div></div><div class="section-heading"><h3>每天的常规切数</h3><span class="small muted">单位：张</span></div><div class="chart" role="img" aria-label="按日期统计拍立得张数">${es.map((date,n)=>{const q=sum(rows.filter(r=>r.date===date)).qty,h=Math.round(q/max*69);return `<div class="bar-col" style="--h:${h}px"><span class="v">${q}</span><div class="bar ${n===es.length-1?'current':''}" style="height:${h}px"></div><small>${date.slice(5).replace('-','.')}</small></div>`}).join('')}</div><div class="section-heading"><h3>常规切数 · 个人与团体</h3><span class="small muted">张数 / 已记录花费</span></div>${db.targets.map(i=>({i,s:sum(rows.filter(r=>matchesTarget(r,i.id)))})).sort((a,b)=>b.s.qty-a.s.qty).map(({i,s:is})=>`<button class="rank-row" data-target="${i.id}" style="width:100%;padding:0;text-align:left">${avatar(i,'sm')}<div class="ranking"><div class="rank-name"><span>${escapeHtml(i.name)}${i.kind==='group'?' · 团体':''}</span><span>${is.qty} 张 · ${money(is.amount)}${is.pending?' · 待补':''}</span></div><div class="track"><span style="width:${s.qty?is.qty/s.qty*100:0}%"></span></div></div></button>`).join('')}<div class="section-heading"><h3>自定义类型分布</h3><span class="small muted">常规 / 特殊</span></div><div class="tag-totals">${db.types.map(t=>`<div><span>${escapeHtml(t.name)}</span><strong>${typeQuantity(rows,t.id)} / ${sum(rows.filter(r=>r.typeId===t.id)).specialQty}</strong></div>`).join('')}${rows.some(r=>!r.typeId)?`<div><span>未填写</span><strong>${typeQuantity(rows,null)} / ${sum(rows.filter(r=>!r.typeId)).specialQty}</strong></div>`:''}</div></div>`+bottom('stats')}
function renderAlbum(){const rows=db.records.filter(r=>albumTarget==='all'||(albumTarget==='special'?r.kind==='special':matchesTarget(r,albumTarget)));const photos=db.photos.filter(p=>rows.some(r=>r.id===p.record)).sort((a,b)=>db.records.find(r=>r.id===b.record).date.localeCompare(db.records.find(r=>r.id===a.record).date));const s=sum(rows);return header('收藏的瞬间','PHOTO ALBUM')+`<div class="body"><div class="choices"><button class="chip ${albumTarget==='all'?'selected':''}" data-album-target="all">全部</button><button class="chip ${albumTarget==='special'?'selected':''}" data-album-target="special">特殊 cheki</button>${db.targets.map(i=>`<button class="chip ${albumTarget===i.id?'selected':''}" data-album-target="${i.id}">${escapeHtml(i.name)}${i.kind==='group'?' · 团体':''}</button>`).join('')}</div><div class="album-head"><span>按日期从近到远</span><span>${photos.length} 张照片 / ${countLabel(s)}</span></div><div class="photo-grid">${photos.map(p=>photo(p)).join('')}</div>${!photos.length?'<div class="empty-state"><h3>照片，可以慢慢补。</h3><p>拍立得已经记好了。<br>下次上传照片，就能在这里翻看。</p></div>':''}<div class="empty-note">特殊 cheki 单独收藏，不重复计入个人切数。<br>照片数量与拍立得张数分开记录。</div></div>`+bottom('album')}
function renderData(){return header('数据与备份','',true)+`<div class="body"><div class="data-banner"><div class="check-circle">${icon('check')}</div><h3>每一次见面，都值得留存</h3><p>定期备份，让记录和照片一起保存。</p><div class="backup-count"><div><strong>${dates(db.records).length}</strong>个记录日</div><div><strong>${db.records.length}</strong>笔记录</div><div><strong>${db.photos.length}</strong>张照片</div></div></div><div class="section-heading"><h3>保存与迁移</h3><span class="small muted">尚未创建备份</span></div><button class="settings-row" data-action="backup"><span class="setting-icon">${icon('download')}</span><span><strong>导出完整备份</strong><small>包含记录、照片和关联关系 · ZIP</small></span><span class="chevron">›</span></button><button class="settings-row" data-action="restore"><span class="setting-icon">${icon('restore')}</span><span><strong>从备份恢复</strong><small>先预览内容，再决定是否替换</small></span><span class="chevron">›</span></button><div class="section-heading"><h3>查看与分析</h3></div><button class="settings-row" data-action="csv"><span class="setting-icon">${icon('file')}</span><span><strong>导出明细表格</strong><small>使用 Excel 等工具查看 · CSV</small></span><span class="chevron">›</span></button><button class="settings-row" data-action="manage-types"><span class="setting-icon">${icon('edit')}</span><span><strong>管理自定义类型</strong><small>自定义、改名或删除 · 每笔单选</small></span><span class="chevron">›</span></button><div class="privacy-note">完整备份可以恢复照片及记录。<br>CSV 仅包含表格明细，不包含照片。</div></div>`+bottom('home')}
const renders={home:renderHome,quick:renderQuick,batch:renderBatch,day:renderDay,idol:renderIdol,stats:renderStats,album:renderAlbum,data:renderData};
function go(screen,keepDraft=false){closeModal();if(screen==='quick'&&!keepDraft)initDraft();if(screen==='batch'&&!batchInfo.date)initBatch();currentScreen=screen;render();history.replaceState(null,'','#'+screen)}
function render(){$('#app').className='view-'+currentScreen;const n=scenes.findIndex(s=>s[0]===currentScreen),s=scenes[n];$('#app').innerHTML=renders[currentScreen]();$('#scene-nav').innerHTML=scenes.map((s,i)=>`<button class="scene-button ${currentScreen===s[0]?'active':''}" data-go="${s[0]}"><span class="n">${String(i+1).padStart(2,'0')}</span>${s[1]}<span class="arrow">↗</span></button>`).join('');$('#scene-index').textContent=`${String(n+1).padStart(2,'0')} / 08`;$('#note-title').textContent=s[2];$('#note-intro').textContent=s[3];$('#note-items').innerHTML=s[4].map(t=>`<li>${t}</li>`).join('');}
function toast(message,canUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${escapeHtml(message)}</span>${canUndo?'<button data-action="undo">撤销</button>':''}`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500)}
function snapshot(){undo=structuredClone(db)}
function modal(title,content){$('#modal').innerHTML=`<div class="modal-overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="row"><h3>${title}</h3><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${content}</section></div>`;$('#modal button')?.focus()}
function closeModal(){$('#modal').innerHTML=''}
function syncAmount(){draft.amount=draft.priceMode==='unit'?(draft.unit===null?null:Math.round(draft.unit*draft.qty*100)/100):draft.amount;const el=$('#quick-summary');if(el)el.textContent=`${draft.qty} 张 · ${money(draft.amount)}`}
function readBatchFields(){batchInfo.name=$('#batch-event')?.value??batchInfo.name;batchInfo.date=$('#batch-date')?.value??batchInfo.date}
function validMoney(value){return value===null||(Number.isFinite(value)&&value>=0&&value<=9999999&&Math.abs(value*100-Math.round(value*100))<1e-6)}
function showTypeManager(){modal('自定义类型',`<p>名称完全由你定义，例如「3寸」或「3寸合照」。每笔最多选择一种类型，也可以暂不填写。</p><div class="tag-manager-list">${db.types.map(t=>`<div class="row"><span>${escapeHtml(t.name)}</span><div><button data-rename-type="${t.id}">改名</button><button data-delete-type="${t.id}">删除</button></div></div>`).join('')||'<p>还没有类型，先创建一个吧。</p>'}</div><label class="field-label" for="type-name">新类型</label><input class="input" id="type-name" placeholder="例如：3寸、宿题、主题"><button class="primary" data-action="save-type">创建类型</button>`)}
function batchModal(index){readBatchFields();const r=index===null?{kind:'regular',targetId:activeTarget,participantIds:[],typeId:null,qty:1,unit:50}:batchRows[index];modal(index===null?'添加一笔':'编辑明细',`<label class="field-label" for="edit-kind">记录分类</label><select id="edit-kind" class="input"><option value="regular" ${r.kind==='regular'?'selected':''}>常规 · 个人或团体</option><option value="special" ${r.kind==='special'?'selected':''}>特殊 cheki · 不计入常规切数</option></select><div id="batch-single" ${r.kind==='special'?'hidden':''}><label class="field-label" for="edit-person">选择一个对象</label><select id="edit-person" class="input">${targetOptions(r)}</select></div><div id="batch-participants" ${r.kind==='special'?'':'hidden'}><label class="field-label">参与偶像（可多选）</label><div class="batch-tags">${targetsOf('idol').map(t=>`<label><input type="checkbox" name="batch-person" value="${t.id}" ${r.participantIds.includes(t.id)?'checked':''}>${escapeHtml(t.name)}</label>`).join('')}</div></div><label class="field-label" for="edit-type">自定义类型（选填 · 单选）</label><select class="input" id="edit-type"><option value="">不填写</option>${db.types.map(t=>`<option value="${t.id}" ${r.typeId===t.id?'selected':''}>${escapeHtml(t.name)}</option>`).join('')}</select><div class="two-fields"><div><label class="field-label" for="edit-qty">张数</label><input class="input" id="edit-qty" type="number" min="1" value="${r.qty}"></div><div><label class="field-label" for="edit-unit">${index!==null&&r.priceMode==='total'?'实付总额':'每张单价'}</label><input class="input" id="edit-unit" type="number" min="0" step="0.01" value="${index!==null&&r.priceMode==='total'?(r.amount??''):(r.unit??'')}"></div></div><p class="error" id="batch-error" role="alert"></p><button class="primary" data-batch-confirm="${index??'new'}">保存明细</button>`)}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.go){go(d.go);return}if(d.date){activeDate=d.date;go('day');return}if(d.target){activeTarget=d.target;profileMode=target(d.target).kind;go('idol');return}if(d.albumTarget){albumTarget=d.albumTarget;go('album');return}if(d.profileMode){profileMode=d.profileMode;specialPerson='all';render();return}if(d.specialPerson){specialPerson=d.specialPerson;profileMode='special';go('idol');return}
 if(d.quickTarget){activeTarget=d.quickTarget;go('quick');return}if(d.draftMode){if(d.draftMode!==draftMode())applyDraftMode(d.draftMode);return}if(d.selectTarget){if(draft.kind==='special'){draft.participantIds=draft.participantIds.includes(d.selectTarget)?draft.participantIds.filter(id=>id!==d.selectTarget):[...draft.participantIds,d.selectTarget];}else draft.targetId=d.selectTarget;render();return}if(d.typeId){draft.typeId=draft.typeId===d.typeId?null:d.typeId;render();return}if(d.period){statPeriod=d.period;render();return}
 if(d.qty){draft.qty=Math.max(1,Math.min(999,draft.qty+Number(d.qty)));syncAmount();render();return}
 if(d.edit){initDraft(d.edit);go('quick',true);return}
 if(d.remove){snapshot();db.records=db.records.filter(r=>r.id!==d.remove);db.photos=db.photos.filter(p=>p.record!==d.remove);render();toast('记录已删除',true);return}
 if(d.addOne){const r=db.records.find(r=>r.id===d.addOne);if(r.priceMode==='total'){initDraft(r.id);draft.qty++;go('quick',true);toast('张数已增加，请核对实付总额');return}snapshot();r.qty++;r.amount=r.unit===null?null:Math.round(r.qty*r.unit*100)/100;render();toast('已追加 1 张',true);return}
 if(d.batchDelta){readBatchFields();const [n,delta]=d.batchDelta.split(',').map(Number),r=batchRows[n];r.qty=Math.max(1,r.qty+delta);if(r.priceMode==='unit')r.amount=r.unit===null?null:Math.round(r.qty*r.unit*100)/100;render();return}
 if(d.batchRemove!==undefined){readBatchFields();batchRows.splice(Number(d.batchRemove),1);render();return}
 if(d.batchEdit!==undefined){batchModal(Number(d.batchEdit));return}
 if(d.batchConfirm!==undefined){const qty=Number($('#edit-qty').value),value=$('#edit-unit').value===''?null:Number($('#edit-unit').value);if(!Number.isInteger(qty)||qty<1||qty>999||!validMoney(value)){$('#batch-error').textContent='请填写 1 至 999 的整数张数，以及有效金额。';return}const previous=d.batchConfirm==='new'?null:batchRows[Number(d.batchConfirm)],mode=previous?.priceMode??'unit';const r={id:previous?.id??'b'+Date.now(),kind:$('#edit-kind').value,targetId:$('#edit-kind').value==='special'?null:$('#edit-person').value,participantIds:$('#edit-kind').value==='special'?[...document.querySelectorAll('[name="batch-person"]:checked')].map(el=>el.value):[],typeId:$('#edit-type').value||null,qty,priceMode:mode,unit:mode==='unit'?value:null,amount:mode==='unit'?(value===null?null:Math.round(qty*value*100)/100):value};if(!validTarget(r)){$('#batch-error').textContent='请选择记录对象；特殊 cheki 至少选择一位偶像。';return}if(previous)batchRows[Number(d.batchConfirm)]=r;else batchRows.push(r);closeModal();render();return}
 if(d.photo){const p=db.photos.find(p=>p.id===d.photo),r=db.records.find(r=>r.id===p.record);modal('收藏的瞬间',`${photo(p)}<p>${r.date.replaceAll('-','.')} ${event(r.event)?' · '+escapeHtml(event(r.event).name):''}<br>所属记录：${escapeHtml(recordTarget(r).name)} · ${r.qty} 张 · ${money(r.amount)}</p><button class="primary" data-date="${r.date}">查看当日记录</button><button class="secondary" data-photo-remove="${p.id}">移除这张照片</button>`);return}
 if(d.photoRemove){snapshot();db.photos=db.photos.filter(p=>p.id!==d.photoRemove);closeModal();render();toast('照片已移除，张数与金额保持不变',true);return}
 if(d.renameType){const t=db.types.find(t=>t.id===d.renameType);modal('修改类型名称',`<label class="field-label" for="rename-type">名称</label><input class="input" id="rename-type" value="${escapeHtml(t.name)}"><p>历史记录会同步显示新名称，张数和金额保持不变。</p><button class="primary" data-confirm-rename="${t.id}">保存名称</button>`);return}
 if(d.confirmRename){const name=$('#rename-type').value.trim();if(!name||db.types.some(t=>t.name===name&&t.id!==d.confirmRename)){toast('请填写不重复的类型名称');return}snapshot();db.types.find(t=>t.id===d.confirmRename).name=name;render();showTypeManager();toast('类型名称已更新',true);return}
 if(d.deleteType){const t=db.types.find(t=>t.id===d.deleteType);modal('删除类型',`<p>删除「${escapeHtml(t.name)}」会移除记录上的这个类型。所有日期、拍立得张数、金额和照片都会保留。</p><button class="primary" data-confirm-delete-type="${t.id}">仅删除这个类型</button><button class="secondary" data-action="manage-types">保留类型</button>`);return}
 if(d.confirmDeleteType){snapshot();const id=d.confirmDeleteType;db.types=db.types.filter(t=>t.id!==id);db.records.forEach(r=>{if(r.typeId===id)r.typeId=null});batchRows.forEach(r=>{if(r.typeId===id)r.typeId=null});if(draft.typeId===id)draft.typeId=null;render();showTypeManager();toast('类型已删除，记录保持不变',true);return}
 switch(d.action){
 case 'undo':if(undo){db=undo;undo=null;if(!target(activeTarget))activeTarget='a';if(draft.typeId&&!db.types.some(t=>t.id===draft.typeId))draft.typeId=null;closeModal();render();toast('已撤销上一步')}break;
 case 'close-modal':closeModal();break;
 case 'new-special':go('quick');applyDraftMode('special');break;
 case 'upload':$('#photo-upload').click();break;
 case 'manage-types':showTypeManager();break;
 case 'save-type':{const name=$('#type-name').value.trim();if(!name){toast('请填写类型名称');break}if(db.types.some(t=>t.name===name)){toast('这个类型已经存在');break}snapshot();const tag={id:'t'+Date.now(),name};db.types.push(tag);if(currentScreen==='quick')draft.typeId=tag.id;render();showTypeManager();toast('自定义类型已添加',true);break}
 case 'save-quick':{
  if(!validTarget(draft)){toast('请选择记录对象；特殊 cheki 至少选择一位偶像');break}
  if(!validDate(draft.date)||!Number.isInteger(draft.qty)||draft.qty<1||draft.qty>999||!validMoney(draft.amount)){toast('请核对日期、张数与金额，金额最多两位小数');break}snapshot();const {photos,eventName,...r}=draft;r.event=resolveEvent(eventName);r.id=r.id||'r'+Date.now();if(draft.id)db.records=db.records.map(x=>x.id===r.id?r:x);else db.records.push(r);photos.forEach((src,n)=>db.photos.push({id:'p'+Date.now()+n,record:r.id,src}));activeDate=r.date;draft={};go('day');toast('记录已保存',true);break}
 case 'batch-add':batchModal(null);break;
 case 'save-batch':{readBatchFields();if(!validDate(batchInfo.date)||!batchRows.length||batchRows.some(r=>!validTarget(r)||!Number.isInteger(r.qty)||r.qty<1||r.qty>999||!validMoney(r.amount))){toast('请填写有效日期，并至少添加一笔记录');break}modal('保存到 '+dayLabel(batchInfo.date),`<p>新增 ${batchRows.length} 笔记录 · ${countLabel(sum(batchRows))}<br>已记录 ${money(sum(batchRows).amount)}</p><p>${batchInfo.name?'活动：'+escapeHtml(batchInfo.name):'未填写活动，记录将直接按日期保存。'}<br>保留当天已有记录，追加本次明细。</p><button class="primary" data-action="confirm-batch">确认保存</button>`);break}
 case 'confirm-batch':{snapshot();const eventId=resolveEvent(batchInfo.name);db.records.push(...batchRows.map((r,n)=>({...r,id:'r'+Date.now()+n,date:batchInfo.date,event:eventId})));activeDate=batchInfo.date;batchRows=[];batchInfo={};go('day');toast('记录已按日期保存',true);break}
 case 'add-idol':modal('新增偶像','<label class="field-label" for="new-idol">昵称</label><input class="input" id="new-idol" placeholder="怎么称呼 TA"><label class="field-label" for="new-group">团体（选填）</label><input class="input" id="new-group" placeholder="个人偶像可以留空"><button class="primary" data-action="save-idol">保存偶像</button>');break;
 case 'save-idol':{const name=$('#new-idol').value.trim();if(!name){toast('请填写昵称');break}snapshot();const i={id:'i'+Date.now(),kind:'idol',name,group:$('#new-group').value.trim(),tone:'gold'};db.targets.push(i);activeTarget=i.id;profileMode='idol';go('idol');toast('偶像已添加',true);break}
 case 'add-group':modal('新增团体','<label class="field-label" for="group-name">团体名称</label><input class="input" id="group-name" placeholder="团切记在哪个团体名下"><p>团体是独立的记录对象，类型可像个人记录一样自由选择。</p><button class="primary" data-action="save-group">保存团体</button>');break;
 case 'save-group':{const name=$('#group-name').value.trim();if(!name){toast('请填写团体名称');break}snapshot();const t={id:'g'+Date.now(),kind:'group',name,group:'团体',tone:'blue'};db.targets.push(t);activeTarget=t.id;profileMode='group';go('idol');toast('团体已添加',true);break}
 case 'backup':modal('导出完整备份',`<p>备份将包含 ${dates(db.records).length} 个记录日、${db.records.length} 笔记录和 ${db.photos.length} 张照片，以及它们之间的关联。</p><p>原型仅展示备份流程，正式版将生成可恢复的 ZIP 文件。</p><button class="primary" data-action="backup-demo">预览备份完成状态</button>`);break;
 case 'backup-demo':closeModal();toast('演示：备份已准备好（未生成 ZIP）');break;
 case 'restore':modal('恢复前预览',`<p>演示备份：2026.10.11<br>${dates(initial.records).length} 个记录日 · ${initial.records.length} 笔记录 · ${initial.photos.length} 张照片</p><p>恢复将替换当前演示数据。正式版会先校验备份并保存当前数据副本，失败时保留原数据。</p><button class="primary" data-action="restore-demo">用示例备份替换演示数据</button><button class="secondary" data-action="close-modal">保留当前数据</button>`);break;
 case 'restore-demo':snapshot();db=structuredClone(initial);activeDate='2026-10-11';activeTarget='a';profileMode='idol';specialPerson='all';closeModal();render();toast('示例备份已恢复',true);break;
 case 'csv':downloadCSV();break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='quick-date')draft.date=e.target.value;if(e.target.id==='quick-event')draft.eventName=e.target.value;if(e.target.id==='batch-date')batchInfo.date=e.target.value;if(e.target.id==='batch-event')batchInfo.name=e.target.value;if(e.target.id==='quick-qty'){draft.qty=Number(e.target.value);syncAmount()}if(e.target.id==='quick-amount'){const value=e.target.value===''?null:Number(e.target.value);if(draft.priceMode==='unit')draft.unit=value;else draft.amount=value;syncAmount()}});
document.addEventListener('change',async e=>{if(e.target.id==='edit-kind'){$('#batch-single').hidden=e.target.value==='special';$('#batch-participants').hidden=e.target.value!=='special';}if(e.target.name==='money-mode'){const next=e.target.value;if(next==='unit')draft.unit=draft.amount===null?null:Math.round(draft.amount/draft.qty*100)/100;draft.priceMode=next;syncAmount();render()}if(e.target.id==='photo-upload'){const files=[...e.target.files];for(const f of files){if(!f.type.startsWith('image/'))continue;if(f.size>10*1024*1024){toast('请选择小于 10 MB 的图片');continue}const src=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(f)});draft.photos.push(src)}render()}});
function downloadCSV(){const rows=[['日期','活动','记录分类','对象类别','归属对象','参与偶像','类型','张数','计入常规切数','实付金额','币种'],...db.records.map(r=>{const e=event(r.event),i=recordTarget(r);return [r.date,e?.name||'',r.kind==='special'?'特殊 cheki':'常规',r.kind==='special'?'特殊':modeNames[i.kind],r.kind==='special'?'':i.name,r.kind==='special'?r.participantIds.map(id=>target(id).name).join(' / '):'',typeName(r),r.qty,r.kind==='regular'?'是':'否',r.amount??'','CNY']})];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cheki-records-2026-10-11.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('明细表格已导出')}
$('#reset-demo').addEventListener('click',()=>{db=structuredClone(initial);draft={};batchRows=[];batchInfo={};activeDate='2026-10-11';activeTarget='a';profileMode='idol';specialPerson='all';albumTarget='all';statPeriod='month';go('home');toast('演示数据已重置')});
render();
